import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.doxMM-x8.js";const h=JSON.parse('{"title":"共享界面组件","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/design-system","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/design-system.md","filePath":"tutorials/design-system.md"}'),r={name:"tutorials/design-system.md"};function n(o,a,l,c,p,d){return s(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="共享界面组件" tabindex="-1">共享界面组件 <a class="header-anchor" href="#共享界面组件" aria-label="Permalink to &quot;共享界面组件&quot;">​</a></h1><p>目标：开发 Lab Word 界面时复用现有组件与 token，并在组件展厅观察状态。先按<a href="./../getting-started/quickstart">快速开始</a>启动并登录应用。</p><h2 id="查看一个真实组件" tabindex="-1">查看一个真实组件 <a class="header-anchor" href="#查看一个真实组件" aria-label="Permalink to &quot;查看一个真实组件&quot;">​</a></h2><p>从左下角账户入口进入设置，再打开设计系统。选择按钮、输入或其他现有场景，对照亮色、暗色、禁用与错误状态。展厅使用演示数据，不更改设备或知识库资料。</p><p><a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/views/src/design-system/design-system-view.tsx" target="_blank" rel="noreferrer">设计系统 View</a>组合场景；共享实现来自 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/ui/src/components/button.tsx" target="_blank" rel="noreferrer">Button</a>、<a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/ui/src/components/input.tsx" target="_blank" rel="noreferrer">Input</a>等 <code>packages/ui/src/components/</code>。颜色和尺寸 token 以 <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/packages/ui/src/styles.css" target="_blank" rel="noreferrer">styles.css</a>为准。</p><h2 id="用于-lab-业务" tabindex="-1">用于 Lab 业务 <a class="header-anchor" href="#用于-lab-业务" aria-label="Permalink to &quot;用于 Lab 业务&quot;">​</a></h2><p>在业务中从 <code>@labos-threejs/ui/components/...</code> 导入已有组件。设备选择、GLB 导入和资产信息留在 Lab 的业务界面；通用 UI 不 import 设备规则。新组件先确认现有组件不能表达所需状态，再将业务状态通过明确参数传入。</p><p>无权限时业务入口应提示拒绝，禁用按钮不能替代后端授权。加载与错误状态保持控件尺寸和键盘焦点稳定；在窄屏和两种语言下核对文字不遮挡其他控件。</p><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/design-system.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> typecheck</span></span></code></pre></div><p>从仓库根目录执行。View 检查验证展厅与可操作场景，类型检查验证组件合同。真实布局、主题与焦点另在浏览器观察；Lab 的实际三维渲染见<a href="./../guides/lab-viewer">Viewer 验证边界</a>。</p><hr><p>源码版本：<code>a10b900dc66b</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/a10b900dc66b8056caf9fb52293975955bf3f276/docs/guides/design-system.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,13)])])}const g=e(r,[["render",n]]);export{h as __pageData,g as default};
